import sys
import base64

content_b64 = ''
replacement = base64.b64decode(content_b64).decode('utf-8')

target_b64 = ''
target = base64.b64decode(target_b64).decode('utf-8')

content = open(r"d:\flutter\ibad_al_rahmann\lib\screens\settings_screen.dart", "r", encoding="utf-8").read()
if target in content:
    content = content.replace(target, replacement)
    open(r"d:\flutter\ibad_al_rahmann\lib\screens\settings_screen.dart", "w", encoding="utf-8").write(content)
    print("Replaced successfully")
else:
    print("Target not found")
